mapper.select:
SELECT vaccine_id AS vaccineId, product_No As productNo, product_name AS productName
, workbench_name AS workbenchName
, COUNT(*) AS totalNum FROM vac_send_drug_record WHERE deleted = 0
AND create_time >= #{createTimeStart}
AND create_time <= #{createTimeEnd}
AND workbench_name = #{workbenchName}
GROUP BY product_name
, workbench_name
